cat > /app/bin/logreport <<'EOF'
#!/bin/bash
awk '
BEGIN { status["2xx"] = status["3xx"] = status["4xx"] = status["5xx"] = 0 }
{
  total++
  ip[$1]++
  # quoted request may contain Apache backslash escapes
  match($0, /"([^"\\]|\\.)*"/)
  request = substr($0, RSTART+1, RLENGTH-2)
  request_end = RSTART + RLENGTH
  if (match(request, /^([A-Z]+) /, m)) method[m[1]]++
  # hour from $4 like [10/Oct/2000:13:55:36
  split($4, a, ":")
  h = substr(a[2], 1, 2) + 0
  hour[h]++
  # status follows the request line
  rest = substr($0, request_end)
  match(rest, /[0-9][0-9][0-9]/, sm)
  cls = int(sm[0]/100) "xx"
  status[cls]++
}
END {
  print "total_requests|" (total+0)
  for (k in method) print "method|" k "|" method[k]
  for (k in ip) print "top_ip|" k "|" ip[k]
  for (k in hour) print "hour|" k "|" hour[k]
  for (k in status) print "status_class|" k "|" status[k]
}' /app/logs/access.log | awk -F'|' '
/^total_requests/ { print; next }
/^method\|/ { m[$2] = $0; next }
/^top_ip\|/ { cnt = $3+0; sub(/^top_ip\|/, ""); ip[cnt " " $0]; next }
/^hour\|/ { h[$2+0] = $0; next }
/^status_class\|/ { s[$2] = $0; next }
END {
  n = asorti(m, ms); for (i=1;i<=n;i++) print m[ms[i]]
  ni = 0
  for (k in ip) { split(k, a, " "); keys[ni++] = a[1] " " k }
  # sort by count desc
  c = 0
  for (k in ip) { split(k, a, " "); arr[c++] = a[1]+0 "\t" k }
  asort(arr, sarr, "@val_num_desc")
  shown = 0
  for (i=1;i<=c && shown<5;i++) {
    line = substr(sarr[i], index(sarr[i], "\t")+1)
    sub(/^[0-9]+ /, "", line)
    print "top_ip|" line
    shown++
  }
  nh = asorti(h, hs, "@ind_num_asc"); for (i=1;i<=nh;i++) print h[hs[i]]
  ns = asorti(s, ss); for (i=1;i<=ns;i++) print s[ss[i]]
}'
EOF
